"""step_log.json -> STEP_LOG.md (one table line per step, then the measured checks per step)."""

from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

HERE = Path(__file__).resolve().parent
log = json.loads((HERE / "step_log.json").read_text())

ICON = {"held": "held", "deviated": "**deviated**", "blocked": "**blocked**"}

out = [
    "# Step log — Head Topology Walkthrough D1 to D11",
    "",
    "Generated by `render_step_log.py` from `step_log.json` (written by `run_walkthrough.py`). Do not edit by hand.",
    "Research document: [Character Head Topology — From Box to Deformation-Ready Face](../../docs/research/topology/Character%20Head%20Topology%20From%20Box%20to%20Deformation-Ready%20Face.md).",
    "Status: **Discovery. Not artist-validated.** Observation and interpretation are kept apart: this file only has observations; interpretation is in [FINDINGS.md](FINDINGS.md).",
    "",
    "Legend. *Tool* names where the operation lives: `src` = Production (`src/core`, `src/mirai`), `playground` = `playground/topology_tools/*`, `lab` = a Lab under `experiments/`. "
    "*Kind*: T = topology-changing, M = move only. *Scope*: local / global. *Origin*: planned (in the document) / corrective (not in the document). "
    "Result: held / deviated / blocked against the document's prediction for that step (the claim is quoted in the detail section).",
    "",
    "| Step | Intent | Tool (where) | Kind | Scope | Origin | Result | Screenshot |",
    "|---|---|---|---|---|---|---|---|",
]
for d in log:
    shot = f"[{Path(d['shot']).name}]({d['shot']})" if d.get("shot") else "—"
    out.append(
        f"| {d['id']} | {d['intent']} | {d['tool']} ({d['where']}) | {'T' if d['topology_changing'] else 'M'} | {d['scope']} | "
        f"{'planned' if d['planned'] else 'corrective'} | {ICON.get(d['verdict'], d['verdict'])} | {shot} |"
    )

c = Counter(d["verdict"] for d in log)
out += ["", f"Totals: {len(log)} log lines — held {c['held']}, deviated {c['deviated']}, blocked {c['blocked']}.", ""]
out += ["## Detail per step", "", "Each check names the claim it tests, the result, and the measured value.", ""]
for d in log:
    out.append(f"### {d['id']} — {d['intent']}  ({ICON.get(d['verdict'], d['verdict'])})")
    out.append("")
    out.append(f"- Document claim: {d['doc_claim']}")
    if d.get("before") and d.get("after"):
        b, a = d["before"], d["after"]
        out.append(f"- Mesh: V/E/F {b['V']}/{b['E']}/{b['F']} -> {a['V']}/{a['E']}/{a['F']}; poles {b['poles_total']} -> {a['poles_total']} "
                   f"(valence {b['poles_by_valence']} -> {a['poles_by_valence']}); symmetric after: {a['symmetric']}")
    elif d.get("after"):
        a = d["after"]
        out.append(f"- Mesh: V/E/F {a['V']}/{a['E']}/{a['F']}; poles {a['poles_total']} (valence {a['poles_by_valence']}); symmetric: {a['symmetric']}")
    for ch in d["checks"]:
        out.append(f"- [{ch['result']}] {ch['claim']} — observed: {ch['observed']}")
    for n in d["observed"]:
        out.append(f"- Note: {n}")
    out.append("")

out += ["## Tool calls in the whole run", "", "```", json.dumps(log[-1].get("n_tool_calls", {})), "```", ""]
(HERE / "STEP_LOG.md").write_text("\n".join(out))
print("wrote STEP_LOG.md", dict(c))
